def rep(p,a,b,n=1):
    s=open(p,encoding='utf-8').read(); c=s.count(a)
    assert c==n,(p,a[:70],c); s=s.replace(a,b); open(p,'w',encoding='utf-8').write(s)
T='rt3_tail.js'
# 궁수 엄호 · 이동만 반복하지 않음
rep(T,"const angleFirst = (W, u, t, dt) => { if (!u.lob || AI6.includes('angle') || (u.angT || 0) >= 1.5) return false;","const archerMoving = (W, u) => !AI6.includes('acover') && W.units.some(o => o !== u && o.alive && o.side === u.side && isFar(o) && ((o.act && o.act.k === 'leap') || (o.mv && ['kite', 'scatter'].includes(o.mv.k) && W.t < o.mv.until)));   // v6.5 다른 궁수가 움직이는 중\nconst angleFirst = (W, u, t, dt) => { if (!u.lob || AI6.includes('angle') || (u.angT || 0) >= 1.5 || (u.inRangeT || 0) > 3.5 || archerMoving(W, u)) return false;   // v6.5 다른 궁수가 움직이면 그 자리에서 엄호 사격 · 3.5초 넘게 못 쐈으면 더 돌지 않음")
rep(T,"  if (g > u.rng || !losClear(W.map, u.x, u.y, t.x, t.y)){ reposition(W, u, t, dt, ordered ? '공격' : '자리 잡기'); return; }\n  let tgt = t, why = '';","  if (g > u.rng || !losClear(W.map, u.x, u.y, t.x, t.y)){ reposition(W, u, t, dt, ordered ? '공격' : '자리 잡기'); return; }\n  u.inRangeT = (u.inRangeT || 0) + dt;   // v6.5 사거리 · 시야 안에서 못 쏜 시간 (쏘면 0)\n  let tgt = t, why = '';")
rep(T,"  let th = shootTh(W, u, tgt);","  let th = shootTh(W, u, tgt); if (u.side === 1 && !AI6.includes('acover') && ((u.inRangeT || 0) > 3.5 || archerMoving(W, u))) th -= 0.2;   // v6.5 이동만 반복하지 않음 · 동료 궁수가 움직이는 사이 엄호")
# 쐐기: 맞닿음 · 돌파 · 막힘
rep(T,"    if (!tip.alive || W.t - V.t0 > 14 || (V.phase === 'breach' && W.t - V.tb > 6)){ L(W, { k: 'wedge', side: 1, s: 'end', tip: V.tip, why: !tip.alive ? '끝이 쓰러짐' : V.phase === 'breach' ? '뚫고 들어감 — 각자 싸움' : '오래 걸림', vis: true }); W.wedge = null; }","""    if (!tip.alive || W.t - V.t0 > 16 || (V.phase === 'breach' && W.t - V.tb > 6) || (V.phase === 'contact' && W.t - V.tc > 5)){ L(W, { k: 'wedge', side: 1, s: 'end', tip: V.tip, why: !tip.alive ? '끝이 쓰러짐' : V.phase === 'breach' ? '뚫고 들어감 — 각자 싸움' : V.phase === 'contact' ? '맞닿았으나 뚫지 못함 (5초)' : '오래 걸림', ok: V.phase === 'breach', vis: true }); W.wedge = null; }
    else if (V.phase === 'contact' && !AI6.includes('wcheck')){   // v6.5 맞닿음 ≠ 돌파: 마디가 맞닿은 자리 너머로 1.2칸 넘게 들어가거나 우리 전열이 끊기면 돌파
      const thru = [V.tip, ...V.sh, ...V.body].map(i => W.units[i]).filter(m => m.alive && ((m.x - V.cp.x) * V.dir.x + (m.y - V.cp.y) * V.dir.y) > 1.2), lb = W.log.some(e => e.k === 'lineBreak' && e.side !== 1 && e.t >= V.tc);
      if (thru.length || lb){ V.phase = 'breach'; V.tb = W.t; L(W, { k: 'wedge', side: 1, s: 'breach', tip: V.tip, b: V.hit, body: V.body, thru: thru.map(m => m.i), why: thru.length ? '전열 너머로 들어감' : '우리 전열이 끊김', obs: true, vis: true }); } }""")
rep(T,"if (hit){ V.phase = 'breach'; V.tb = W.t; L(W, { k: 'wedge', side: 1, s: 'breach', tip: V.tip, b: hit.i, body: V.body, obs: true, vis: true }); } }","if (hit){ if (AI6.includes('wcheck')){ V.phase = 'breach'; V.tb = W.t; L(W, { k: 'wedge', side: 1, s: 'breach', tip: V.tip, b: hit.i, body: V.body, obs: true, vis: true }); } else { const dd = dist(tip, hit) || 1; V.phase = 'contact'; V.tc = W.t; V.hit = hit.i; V.cp = { x: hit.x, y: hit.y }; V.dir = { x: (hit.x - tip.x) / dd, y: (hit.y - tip.y) / dd }; L(W, { k: 'wedge', side: 1, s: 'contact', tip: V.tip, b: hit.i, obs: !!tip.seenBy, vis: true }); } } }")
rep(T,"  if (V.phase === 'breach'){ if (isTip || si >= 0) return false;","  if (V.phase === 'breach' || V.phase === 'contact'){ if (isTip || si >= 0) return false;")
